descriptions={'Fantasy':'Enter an imagined world and explore how setting, language, and curiosity shape a story.','Growing up':'Follow changing relationships and reflect on character, belonging, and personal growth.','Adventure':'Follow a journey, track turning points, and consider whose perspective shapes the adventure.','Society':'Explore social expectations, power, and the relationship between individuals and their communities.','Animals':'Read for narrative voice, empathy, and the relationship between people and the natural world.','Science fiction':'Investigate how imagined discoveries raise questions about science, responsibility, and society.','Mystery':'Follow clues, compare explanations, and distinguish an inference from evidence.','Historical fiction':'Consider the relationship between an individual story and its historical setting.','Gothic fiction':'Examine suspense, atmosphere, narrative reliability, and moral responsibility.','Psychology':'A challenging text for exploring perspective, uncertainty, and human motivation.','Tragedy':'Read or perform scenes to investigate conflict, dramatic structure, and consequences.','Drama':'Explore dialogue, dramatic tension, and how meaning changes in performance.','Comedy':'Look closely at misunderstanding, irony, social conventions, and performance.','Fables':'Compare short stories and examine how a simple narrative communicates a larger idea.','Fairy tales':'Compare traditional stories, recurring patterns, and different interpretations.'}
target=Path('front-end/src/bookExpansion.js'); cache=Path('.work/book-sources');cache.mkdir(parents=True,exist_ok=True)
def fetch(entry):
 n,title,author,genre,stage=entry;url=f'https://www.gutenberg.org/ebooks/{n}';file=cache/f'{n}.html'
 try:
  if not file.exists():file.write_bytes(urllib.request.urlopen(url,timeout=40).read())
  page=file.read_text(encoding='utf-8');heading=re.search(r'<h1[^>]*>(.*?)</h1>',page,re.S)
  canonical=html.unescape(re.sub('<.*?>','',heading.group(1))).strip() if heading else ''
  if not canonical:raise ValueError('Missing verified title')
  book={'id':f'pg-{n}','title':title,'author':author,'subject':'drama' if genre in ['Tragedy','Drama','Comedy'] else 'english','stages':['Grade 8','IGCSE'] if stage=='Grade 8' else ['IGCSE','IB'] if stage=='IGCSE' else ['IB'],'description':descriptions[genre],'topics':[genre,'Literature','Close reading'],'access':'public-domain','url':url,'source':url,'connection':'Optional wider reading','rights':'Project Gutenberg lists this edition as public domain in the USA. Check local copyright rules and the edition’s credits. Historical attitudes, violence, or other mature themes may need discussion; stage labels are reading suggestions, not school endorsements.','language':'English','verifiedTitle':canonical}
  if n in [11,45,113,120,55,1661]:
   match=re.search(r'href="([^"]+)"[^>]*type="text/plain',page)
   texturl='https://www.gutenberg.org/cache/epub/'+str(n)+'/pg'+str(n)+'.txt'
   raw=urllib.request.urlopen(texturl,timeout=40).read()
   if b'*** START OF THE PROJECT GUTENBERG EBOOK' not in raw:raise ValueError('Invalid full text')
   Path('front-end/public/books/'+str(n)+'.txt').write_bytes(raw);book['local']='/books/'+str(n)+'.txt'
  print(n,canonical,flush=True);return book
 except Exception as e:print('FAILED',n,str(e),flush=True);return None
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as executor:books=list(filter(None,executor.map(fetch,entries)))
target.write_text('export const EXTRA_BOOKS='+json.dumps(books,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
print('Verified books:',len(books),flush=True)
